class Kitap:
  def __init__(self, ad):
    self.ad = ad
  def __str__(self):
    return f'Kitap Adı: {self.ad}'

k = Kitap('Yüzüklerin Efendisi')
print(k)

class Sepet:
  def __init__(self):
    self.urunler = ['Elma', 'Armut', 'Muz']
  def __len__(self):
    return len(self.urunler)

s = Sepet()
print('Sepetteki ürün sayısı:', len(s))

class Kasa:
  def __init__(self, para):
    self.para = para
  def __add__(self, diger_kasa):
    return Kasa(self.para + diger_kasa.para)

k1 = Kasa(100)
k2 = Kasa(50)
toplam = k1 + k2
print('Toplam Para:', toplam.para)

class Insan:
  def __init__(self, tc_no):
    self.tc_no = tc_no
  def __eq__(self, diger):
    return self.tc_no == diger.tc_no

i1 = Insan(12345)
i2 = Insan(12345)
print('Aynı kişiler mi?', i1 == i2)

class Selamlayici:
  def __call__(self, isim):
    print(f'Merhaba {isim}!')

selam_obj = Selamlayici()
selam_obj('Ali') # Nesneyi fonksiyon gibi çağırdık
